mapper.select:
SELECT A.EQP_G,B.MODULE,A.MODULE_OWNER,A.OPE_NO,A.RULE ,CASE WHEN A.RULE = 'SDEPT' THEN '指定课' WHEN A.RULE = 'PRODUCT_OWNER' THEN '指定产品Owner' WHEN A.RULE = 'LAST_MAIN_OPENO_RULE' THEN 'Follow 上一主站点' END RULE_DESC ,A.SDEPT_ID,A.UPDATE_TIME,A.TECH,A.UPDATE_FLAG ,A.LOCATION,C.SDEPT_CNAME FROM A1MFG.HOLD_TO_SDEPT_RULE A LEFT JOIN ( SELECT DISTINCT EQP_G,MODULE FROM PWEB.EQP_ID_USE_STD UNION SELECT DISTINCT EQP_G,MODULE FROM PWEB.EQP_ID_USE_STD_A3 )B ON A.EQP_G = B.EQP_G LEFT JOIN( SELECT DEPT_ID||DECODE(SUBDEPT_ID,NULL,NULL,'-')|| DECODE(SUBDEPT_ID,NULL,NULL,SUBDEPT_ID) SDEPT_ID, DEPT_CNAME||DECODE(SDEPT_CNAME,NULL,NULL,'(')||DECODE(SDEPT_CNAME,NULL,NULL,SDEPT_CNAME)||DECODE(SDEPT_CNAME,NULL,NULL,')')SDEPT_CNAME FROM( SELECT DISTINCT DEPT_ID,SUBDEPT_ID,DEPT_CNAME,SDEPT_CNAME FROM WORKFLOW.HR_USERS ) )C ON A.SDEPT_ID = C.SDEPT_ID WHERE 1=1
AND MODULE_OWNER = #{moduleOwner,jdbcType=VARCHAR}
AND #{eqpG,jdbcType=VARCHAR} like REPLACE(A.EQP_G,'*','%')
AND B.module = #{module,jdbcType=VARCHAR}
AND A.UPDATE_FLAG = #{updateFlag,jdbcType=VARCHAR}
ORDER BY A.MODULE_OWNER,A.TECH,A.EQP_G,A.OPE_NO

SELECT EQP_G,MODULE_OWNER,OPE_NO,RULE,SDEPT_ID,UPDATE_USER,UPDATE_TIME,TECH,UPDATE_FLAG,LOCATION FROM A1MFG.HOLD_TO_SDEPT_RULE
WHERE MODULE_OWNER = #{moduleOwner,jdbcType=VARCHAR} AND EQP_G = #{eqpG,jdbcType=VARCHAR} AND OPE_NO = #{opeNo,jdbcType=VARCHAR} AND LOCATION = #{location,jdbcType=VARCHAR} AND TECH = #{tech,jdbcType=VARCHAR}
AND ROWNUM = 1

MERGE INTO A1MFG.HOLD_TO_SDEPT_RULE A USING( SELECT TRIM(UPDATE_FLAG)UPDATE_FLAG ,TRIM(LOCATION)LOCATION ,TRIM(EQP_G)EQP_G ,TRIM(MODULE_OWNER)MODULE_OWNER ,CASE WHEN TRIM(RULE) = '指定课' THEN 'SDEPT' WHEN TRIM(RULE) = '指定产品Owner' THEN 'PRODUCT_OWNER' WHEN TRIM(RULE) = 'Follow 上一主站点' THEN 'LAST_MAIN_OPENO_RULE' END RULE ,TRIM(SDEPT_ID)SDEPT_ID,UPDATE_USER FROM(
SELECT 'static'UPDATE_FLAG , #{item.Location,jdbcType=VARCHAR}LOCATION ,#{item.eqpG,jdbcType=VARCHAR}EQP_G ,#{item.moduleOwner,jdbcType=VARCHAR}MODULE_OWNER ,#{item.rule,jdbcType=VARCHAR}RULE ,#{item.sdeptId,jdbcType=VARCHAR}SDEPT_ID ,#{item.updateUser,jdbcType=VARCHAR} UPDATE_USER FROM DUAL
) ) B ON(A.LOCATION=B.LOCATION AND A.EQP_G = B.EQP_G AND A.MODULE_OWNER = B.MODULE_OWNER AND A.UPDATE_FLAG = B.UPDATE_FLAG) WHEN MATCHED THEN UPDATE SET A.RULE = B.RULE ,A.SDEPT_ID = B.SDEPT_ID ,A.UPDATE_USER = B.UPDATE_USER,A.UPDATE_TIME = SYSDATE WHEN NOT MATCHED THEN INSERT (EQP_G, MODULE_OWNER, OPE_NO, RULE, SDEPT_ID, UPDATE_USER, UPDATE_TIME, TECH, UPDATE_FLAG, LOCATION) VALUES(B.EQP_G, B.MODULE_OWNER,'*',B.RULE,B.SDEPT_ID,B.UPDATE_USER,SYSDATE,'*',B.UPDATE_FLAG,B.LOCATION)
